'use strict';

// MODULES //

var absf = require( '@stdlib/math/base/special/absf' );
var floorf = require( '@stdlib/math/base/special/floorf' );
var logf = require( '@stdlib/math/base/special/logf' );
var powf = require( '@stdlib/math/base/special/powf' );
var roundf = require( '@stdlib/math/base/special/roundf' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isInfinite = require( '@stdlib/math/base/assert/is-infinite' );


// MAIN //

/**
* Round a single-precision floating-point number to `n` significant figures in base `b`.
*
* @param {number} x - input value
* @param {number} n - number of significant figures
* @param {number} b - base (integer >= 2)
* @returns {number} rounded value
*
* @example
* var v = roundsdf( 3.14159, 3, 10 );
* // returns 3.14
*
* @example
* var v = roundsdf( 3.14159, 1, 10 );
* // returns 3.0
*
* @example
* var v = roundsdf( 12368.0, 2, 10 );
* // returns 11999.999430030612
*
* @example
* var v = roundsdf( 0.0313, 2, 2 );
* // returns 0.03125
*/
function roundsdf( x, n, b ) {
	var ax;
	var e;
	var s;

	if ( isnan( x ) || n < 1 || b < 2 ) {
		return NaN;
	}
	if ( isInfinite( x ) || x === 0.0 ) {
		return x;
	}
	ax = absf( x );
	e = floorf( logf( ax, b ) );
	s = powf( b, ( n-1 ) - e );
	return roundf( x*s ) / s;
}


// EXPORTS //

module.exports = roundsdf;
